CREATE FUNCTION ultrabrain.review_dependency_page_changed() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $f$
BEGIN
 IF TG_OP='UPDATE' AND NEW.compiled_truth IS NOT DISTINCT FROM OLD.compiled_truth
  AND NEW.timeline IS NOT DISTINCT FROM OLD.timeline AND NEW.title IS NOT DISTINCT FROM OLD.title
  AND NEW.frontmatter IS NOT DISTINCT FROM OLD.frontmatter AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash
  AND NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug
  AND NEW.source_id IS NOT DISTINCT FROM OLD.source_id THEN RETURN NEW; END IF;
 IF TG_OP!='INSERT' THEN PERFORM ultrabrain.invalidate_review_dependents(OLD.source_id,OLD.slug); END IF;
 IF TG_OP='INSERT' THEN PERFORM ultrabrain.invalidate_review_dependents(NEW.source_id,NEW.slug);
 ELSIF TG_OP='UPDATE' AND (NEW.slug IS DISTINCT FROM OLD.slug OR NEW.source_id IS DISTINCT FROM OLD.source_id)
 THEN PERFORM ultrabrain.invalidate_review_dependents(NEW.source_id,NEW.slug); END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $f$

CREATE FUNCTION ultrabrain.review_dependency_policy_changed() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $f$
BEGIN
 IF NEW.status IN ('retracted','superseded') THEN
  IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
   PERFORM ultrabrain.invalidate_review_dependents(NEW.source_id,NEW.slug);
  END IF;
 END IF;
 RETURN NEW;
END $f$
